local _, WFJ = ...
WFJ.Data.add("book", {
  ["60329d525a63b3a4"] = { "Tuttavia, negli ultimi giorni della Seconda Guerra, quando la vittoria dell'Orda sull'⟦Alliance=Alleanza⟧ sembrava quasi certa, scoppiò una terribile faida tra i due orchi più potenti di Azeroth. Mentre Doomhammer preparava l'assalto finale contro la Capitale di Lordaeron, un assalto che avrebbe schiacciato gli ultimi resti dell'⟦Alliance=Alleanza⟧, Gul'dan e i suoi seguaci abbandonarono i loro posti e presero il mare.", "." },
  ["6048934923d70f40"] = { "Bene, a questo punto dovresti avere pronti le cariche NG-5 e i detonatori. Li ho etichettati per te... Il blu è per la segheria. Il rosso è per la ⟦Windshear Mine=Miniera di Tagliavento⟧.\n\nHo fatto un po' di ricognizione: nella ⟦Windshear Crag=Landa di Tagliavento⟧ ci sono così tanti esplosivi che non dovresti avere alcun problema a entrare, piazzare le cariche e uscire prima di farle detonare.\n\nRicorda, è un diversivo. Allontanati dai carri prima che arrivino i goblin a controllare cos'è successo, poi intrufolati alle loro spalle.", "." },
  ["6094def7f280652a"] = { "La dimora dei worgen è un luogo oscuro, un luogo da incubo. Se quel mondo offre rifugi al sicuro dai worgen maledetti, le mie ricerche non hanno rivelato alcun baluardo del genere.\n\nE se si considerano la ferocia e la malvagità dei worgen, è probabile che tali baluardi non esistano.\n\nSi presume che i worgen si accontentino di restare nel loro mondo perché, sebbene alcuni di loro possiedano una magia potente, non hanno mai tentato di raggiungere Azeroth di loro iniziativa.\n\nE di questo possiamo ritenerci fortunati.", "." },
  ["6095d0fadd05c7ec"] = { "Invar One-Arm\nIl primo capo degli assassini della ⟦Scarlet Crusade=Crociata Scarlatta⟧ \nCittadino di Dalaran\nVisto l'ultima volta sulle coste di Nordania", "." },
  ["60b0b5f6bd713cbe"] = { "Molti dei sopravvissuti tra gli ⟦Highborne=Alti Nobili⟧ originari, però, divennero inquieti. Come Illidan prima di loro, caddero vittime dell'astinenza che seguì la perdita delle magie tanto bramate. Erano tentati di attingere alle energie del ⟦Well of Eternity=Pozzo dell'Eternità⟧ e di abbandonarsi alle loro pratiche magiche. Dath'Remar, il capo impetuoso e sfrontato degli ⟦Highborne=Alti Nobili⟧, cominciò a deridere pubblicamente i druidi, chiamandoli codardi perché si rifiutavano di usare la magia che, a suo dire, spettava loro di diritto.", "." },
  ["60d2081a80ba0438"] = { "La Madre Terra, col cuore gonfio di dolore per la sorte dei suoi figli, non sopportava di vederli cadere in disgrazia. Nel suo strazio si strappò gli occhi e li lanciò a ruotare nei cieli stellati e infiniti. An'she e Mu'sha, cercando di alleviare l'uno il dolore dell'altra, non poterono che inseguire il tenue bagliore l'uno dell'altra attraverso il cielo. I gemelli si inseguono ancora a ogni giro del mondo.", "." },
})
